import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { ActivateSellerComponent } from './activate-seller.component';

const routes: Routes = [{ path: '', component: ActivateSellerComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ActivateSellerRoutingModule { }
